import{_ as a,o as e,c as l,ag as i}from"./chunks/framework.CtWPcAmt.js";const b=JSON.parse('{"title":"第 19 章：工作事务案例——把一摊材料变成六份交付文档","description":"用本书第 5 章「统一基准任务」的真实过程，演示工作事务类任务从原始需求到可复用资产的完整闭环。","frontmatter":{"title":"第 19 章：工作事务案例——把一摊材料变成六份交付文档","description":"用本书第 5 章「统一基准任务」的真实过程，演示工作事务类任务从原始需求到可复用资产的完整闭环。","layout":"doc","lastUpdated":true},"headers":[],"relativePath":"guide/19-work-case.md","filePath":"guide/19-work-case.md","lastUpdated":null}'),r={name:"guide/19-work-case.md"};function o(d,t,n,h,s,c){return e(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="第-19-章-工作事务案例——把一摊材料变成六份交付文档" tabindex="-1">第 19 章：工作事务案例——把一摊材料变成六份交付文档 <a class="header-anchor" href="#第-19-章-工作事务案例——把一摊材料变成六份交付文档" aria-label="Permalink to &quot;第 19 章：工作事务案例——把一摊材料变成六份交付文档&quot;">​</a></h1><h2 id="案例摘要" tabindex="-1">案例摘要 <a class="header-anchor" href="#案例摘要" aria-label="Permalink to &quot;案例摘要&quot;">​</a></h2><ul><li>使用场景：工作（材料整理与文档交付）</li><li>使用者基础：零基础可复现</li><li>使用的 Agent：桌面 Agent（第 6 章任选一款，本例为多款产品统一实测）</li><li>完成时间：约 2–6 分钟/款（2026-08-12 实测）</li><li>风险等级：低</li><li>最终交付物：6 份 Markdown 文档 + 验收记录</li></ul><h2 id="任务背景" tabindex="-1">任务背景 <a class="header-anchor" href="#任务背景" aria-label="Permalink to &quot;任务背景&quot;">​</a></h2><p>写这套教程时，我需要知道七款桌面 Agent 用同一套材料、同一个任务，分别能做到什么程度——这要求先造一个「统一任务」：同样的输入、同样的要求、同样的验收口径。这个需求本身就是最典型的工作事务：<strong>把一摊零散材料，整理成结构化的多份交付文档。</strong></p><h2 id="原始需求" tabindex="-1">原始需求 <a class="header-anchor" href="#原始需求" aria-label="Permalink to &quot;原始需求&quot;">​</a></h2><blockquote><p>「把 <code>input/</code> 文件夹里 7 份 AI Agent 教程材料整理一下，输出 6 份文档：项目总结、信息缺口、教程目录、写作计划、待办清单、自检报告。」</p></blockquote><p>（这是作者整理后的原始表达；更早的模糊版是「帮我总结一下这些资料」——第 7 章任务卡就是解决这个差异的。）</p><h2 id="任务判断" tabindex="-1">任务判断 <a class="header-anchor" href="#任务判断" aria-label="Permalink to &quot;任务判断&quot;">​</a></h2><ul><li>为什么适合 Agent：规则明确（有输出要求清单）、材料齐备（7 份文件）、可验证（6 份 + 哈希）、不依赖实时信息 → 第 2 章检查表判定 L1；</li><li>交给 Agent：读取材料、整理、生成 6 份文档、自检；</li><li>人必须做的：设计任务卡与验收标准、验收边界（它读了什么）、下最终结论。</li></ul><h2 id="整理后的任务卡" tabindex="-1">整理后的任务卡 <a class="header-anchor" href="#整理后的任务卡" aria-label="Permalink to &quot;整理后的任务卡&quot;">​</a></h2><ul><li><strong>目标</strong>：生成 6 份指定文档，用于七款产品统一实测；</li><li><strong>上下文</strong>：材料来自真实教程项目；零基础读者；Qoder/TraeWork/ZCode 只用中国版资料；</li><li><strong>输入材料</strong>：<code>input/</code> 下 7 份文件（简报、笔记、读者反馈、产品事实表、流程图、输出要求）；</li><li><strong>范围与约束</strong>：只读 <code>input/</code>；输出到 <code>output/</code>；不联网；不修改输入文件；不把 Claude 封号原因写成事实；</li><li><strong>交付物</strong>：<code>01-project-summary.md</code> 等 6 份文件（结构见 <code>OUTPUT-REQUIREMENTS.md</code>）；</li><li><strong>验收标准</strong>：6 份齐全、按要求结构、区分事实/推断、自检含输入清单与边界说明、不虚构。</li></ul><h2 id="执行过程-七款产品的统一流程" tabindex="-1">执行过程（七款产品的统一流程） <a class="header-anchor" href="#执行过程-七款产品的统一流程" aria-label="Permalink to &quot;执行过程（七款产品的统一流程）&quot;">​</a></h2><ol><li>建独立目录：<code>runs/2026-08-12-产品名/</code> 下分 <code>input/</code>、<code>output/</code>；</li><li>记录输入基线：7 份文件 SHA-256 哈希；</li><li>打开产品 → 选运行目录 → 粘贴任务卡 → 发送；</li><li>观察执行：计时、记录人工介入与权限弹窗（第 9 章过程记录表）；</li><li>完成后：核对 6 份文件、复算哈希、记录问题。</li></ol><h2 id="出现的问题-七款产品的真实表现" tabindex="-1">出现的问题（七款产品的真实表现） <a class="header-anchor" href="#出现的问题-七款产品的真实表现" aria-label="Permalink to &quot;出现的问题（七款产品的真实表现）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>出现产品</th><th>影响</th></tr></thead><tbody><tr><td>无弹窗却读取了 input 外文件</td><td>Qoder、Hermes</td><td>边界违规，产物引用了工作区其他文件</td></tr><tr><td>自检称全部通过，实际待办未勾选</td><td>Qoder</td><td>自检不可信</td></tr><tr><td>文件写错目录后自动恢复</td><td>Hermes</td><td>过程违规但自动恢复成功</td></tr><tr><td>产物 6 份但变更列表只显示 5 份</td><td>WorkBuddy</td><td>展示不一致，需两处核对</td></tr><tr><td>把「材料裁剪缺失」当成「项目缺失」</td><td>多数产品</td><td>上下文不足导致误判</td></tr></tbody></table><h2 id="修正与判断" tabindex="-1">修正与判断 <a class="header-anchor" href="#修正与判断" aria-label="Permalink to &quot;修正与判断&quot;">​</a></h2><ul><li>不重跑：交付物内容本身合格，问题集中在边界与自检 → 在验收记录中单独标注「过程问题」；</li><li>不采信自检：独立核对产物与读取记录（第 10 章）；</li><li>结论分级：能力（交付合格）与边界（越权）分开评价，成为第 6 章选择表的两个独立维度。</li></ul><h2 id="最终结果与验收" tabindex="-1">最终结果与验收 <a class="header-anchor" href="#最终结果与验收" aria-label="Permalink to &quot;最终结果与验收&quot;">​</a></h2><ul><li>7 款可运行产品全部 6/6 交付、输入哈希 7/7 一致；</li><li>用时 2–6 分钟不等；成本单位各不相同（Credits/积分/人民币/API），不横比；</li><li>详细数据见第 5 章各产品页与 <code>research/runs/</code>。</li></ul><h2 id="复盘" tabindex="-1">复盘 <a class="header-anchor" href="#复盘" aria-label="Permalink to &quot;复盘&quot;">​</a></h2><ul><li>Agent 做得好的：结构化整理、信息缺口分类、按任务卡执行；</li><li>人必须介入的：边界检查、自检质疑、结论定夺；</li><li>下次可省略：无（统一实测本身就足够简单）；</li><li>可沉淀的资产：任务卡模板（第 7 章）、验收清单「边界检查」项（第 10 章）、「无弹窗 ≠ 合规」原则（第 8 章）、产品边界评分（第 6 章）。</li></ul><h2 id="给新手的最小版本" tabindex="-1">给新手的最小版本 <a class="header-anchor" href="#给新手的最小版本" aria-label="Permalink to &quot;给新手的最小版本&quot;">​</a></h2><p>30 分钟复现：找 3 份你手头的文档 → 按第 7 章任务卡模板写「生成一份总结 + 一份待办」→ 用你选的产品跑一次 → 按第 10 章清单验收（重点检查：它有没有碰材料以外的文件）。<strong>工作事务类任务的关键不是「生成」，而是「边界与验收」。</strong></p>',24)])])}const p=a(r,[["render",o]]);export{b as __pageData,p as default};
